<script setup lang="ts">
import FeedFieldEditor from './FeedFieldEditor.vue'
import {computed} from 'vue'
import {feedMappingCatalog,type FeedMapping,type FeedField} from './feed-mapping'
const props=defineProps<{locale:'en'|'zh-CN'}>()
const model=defineModel<FeedMapping>({required:true})
const t=(key:keyof typeof feedMappingCatalog.en)=>feedMappingCatalog[props.locale][key]
const fields=computed(()=>[
 {key:'period',title:t('periodField'),value:model.value.period},
 {key:'draw_time',title:t('drawTimeField'),value:model.value.draw_time},
 ...(model.value.time_period?[{key:'time_period',title:t('timePeriodField'),value:model.value.time_period}]:[]),
 ...(model.value.schedule==='source'&&model.value.next_period?[{key:'next_period',title:t('nextPeriodField'),value:model.value.next_period},{key:'next_draw_time',title:t('nextTimeField'),value:model.value.next_draw_time}]:[])
])
const scopes=[['regular','regularField'],['special','specialField'],['digits','digitsField']] as const
function formatChanged(){model.value.browser=model.value.format==='browser'?{wait_selector:'',timeout_ms:10000,entry_url:'',max_redirects:0,ignored_requests:[],json_requests:[]}:undefined}
function scheduleChanged(){model.value.next_period=model.value.schedule==='source'?{path:'',attribute:''}:null;model.value.next_draw_time=model.value.schedule==='source'?{path:'',attribute:''}:null}
function toggleScope(key:'regular'|'special'|'digits'){model.value[key]=model.value[key]?null:{path:'',attribute:'',separator:'',offset:0,count:1}}
function ignoredInput(e:Event){model.value.browser!.ignored_requests=(e.target as HTMLTextAreaElement).value.split('\n').map(s=>s.trim()).filter(Boolean)}
function addQuery(){const b=model.value.browser!;if(!b.json_requests)b.json_requests=[];b.json_requests.push({id:'',url:'',method:'GET',body:''})}
function field(value:FeedField|null){return value!}
</script>
<template><section class="feed-mapping" data-testid="feed-mapping"><h3>{{t('mapping')}}</h3><div class="feed-fields"><label>{{t('format')}}<select v-model="model.format" @change="formatChanged"><option value="json">{{t('jsonFormat')}}</option><option value="html">{{t('htmlFormat')}}</option><option value="browser">{{t('browserFormat')}}</option></select></label><template v-if="model.format==='browser'&&model.browser"><label>{{t('waitSelector')}}<input v-model="model.browser.wait_selector" required maxlength="512" /></label><label>{{t('entryURL')}}<input v-model="model.browser.entry_url" type="url" /></label><label>{{t('redirects')}}<input v-model.number="model.browser.max_redirects" type="number" min="0" max="5" /></label><label>{{t('ignoredRequests')}}<textarea :value="model.browser.ignored_requests?.join('\n')" @input="ignoredInput" rows="3" /></label><label>{{t('renderTimeout')}}<input v-model.number="model.browser.timeout_ms" type="number" min="1000" max="10000" required /></label></template><label>{{t('schedule')}}<select v-model="model.schedule" @change="scheduleChanged"><option value="interval">{{t('intervalSchedule')}}</option><option value="source">{{t('sourceScheduleMode')}}</option></select></label><label>{{t('timeFormat')}}<select v-model="model.time_format"><option v-for="kind in (['rfc3339','unix_seconds','unix_millis','custom'] as const)" :key="kind" :value="kind">{{t(kind)}}</option></select></label><template v-if="model.time_format==='custom'"><label>{{t('timeLayout')}}<input v-model="model.time_layout" required /></label><label>{{t('timezone')}}<input v-model="model.timezone" required /></label></template></div><p>{{t('mappingHelp')}}</p><p v-if="model.format==='html'">{{t('domHelp')}}</p><p v-if="model.format==='browser'">{{t('browserHelp')}}</p><p v-if="model.time_format==='custom'">{{t('timeHelp')}}</p>
<section v-if="model.format==='browser'&&model.browser"><h4>{{t('queries')}}</h4><button type="button" class="button button-secondary" @click="addQuery">{{t('addQuery')}}</button><div v-for="(q,index) in model.browser.json_requests" :key="index" class="feed-fields feed-group"><label>{{t('queryID')}}<input v-model="q.id" required maxlength="40" /></label><label>{{t('queryURL')}}<input v-model="q.url" type="url" required /></label><label>{{t('queryMethod')}}<select v-model="q.method"><option value="GET">GET</option><option value="POST">POST</option></select></label><label v-if="q.method==='POST'">{{t('queryBody')}}<input v-model="q.body" maxlength="4096" /></label><button type="button" class="button button-secondary" @click="model.browser!.json_requests!.splice(index,1)">{{t('removeQuery')}}</button></div></section><label v-if="model.schedule==='source'" class="check"><input type="checkbox" :checked="!!model.next_period" @change="model.next_period=model.next_period?null:{path:'',attribute:''};model.next_draw_time=model.next_period?{path:'',attribute:''}:null" />{{t('readNext')}}</label><p>{{t('captureHelp')}}</p><p>{{t('timeStrictHelp')}}</p><label class="check"><input type="checkbox" :checked="!!model.time_period" @change="model.time_period=model.time_period?undefined:{path:'',attribute:''}" />{{t('verifyTimePeriod')}}</label>
<div v-for="entry in fields" :key="entry.key" class="feed-group"><h4>{{entry.title}}</h4><div class="feed-fields"><FeedFieldEditor :field="field(entry.value)" :title="entry.title" :mapping="model" :locale="locale" /></div></div>
<div v-for="[key,title] in scopes" :key="key" class="feed-group"><label class="check"><input type="checkbox" :checked="!!model[key]" @change="toggleScope(key)" />{{t(title)}}</label><div v-if="model[key]" class="feed-fields"><FeedFieldEditor :field="model[key]!" :title="t(title)" :mapping="model" :locale="locale" /><label>{{t(title)}} · {{t('separator')}}<input v-model="model[key]!.separator" /></label><label>{{t(title)}} · {{t('offset')}}<input v-model.number="model[key]!.offset" type="number" min="0" required /></label><label>{{t(title)}} · {{t('count')}}<input v-model.number="model[key]!.count" type="number" min="1" max="100" required /></label></div></div>
<label class="check"><input type="checkbox" :checked="!!model.complete" @change="model.complete=model.complete?null:{path:'',attribute:'',equals:''}" />{{t('completeField')}}</label><div v-if="model.complete" class="feed-fields"><label>{{t('completeField')}} · {{t('path')}}<input v-model="model.complete.path" required /></label><label v-if="model.format!=='json'">{{t('completeField')}} · {{t('attribute')}}<input v-model="model.complete.attribute" /></label><label>{{t('completeEquals')}}<input v-model="model.complete.equals" /></label></div>
<div class="feed-fields"><label>{{t('periodQuery')}}<input v-model="model.period_query" maxlength="120" /></label><label>{{t('gameQuery')}}<input v-model="model.game_query" maxlength="120" /></label></div></section></template>
<style scoped>.feed-mapping{min-width:0}.feed-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.feed-group{border-top:1px solid var(--line);padding-top:10px}.feed-mapping h4{font-size:14px;margin:8px 0}.feed-mapping p{overflow-wrap:anywhere}.feed-mapping :deep(label){display:grid;grid-template-columns:minmax(0,1fr);gap:6px;margin-bottom:10px;min-width:0}.feed-mapping :deep(input),.feed-mapping :deep(select),.feed-mapping :deep(textarea){width:100%;min-width:0;box-sizing:border-box;min-height:44px;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:var(--radius-sm);padding:8px;font:inherit}.feed-mapping .check{display:flex;align-items:center;gap:8px}.feed-mapping .check input{width:18px}@media(max-width:620px){.feed-fields{grid-template-columns:minmax(0,1fr)}}</style>
